import colors from "./colors";
import typography from "./typography";

/**
 * Emits the brand tokens as CSS custom properties so plain stylesheets can
 * use them without a second copy of the palette. Tokens stay the single
 * source of truth: edit colors.ts, every consumer follows.
 */
const cssVariables = `
:root {
  --kr-background: ${colors.background};
  --kr-background-alt: ${colors.backgroundAlt};
  --kr-primary: ${colors.primary};
  --kr-primary-dark: ${colors.primaryDark};
  --kr-accent: ${colors.accent};
  --kr-accent-dark: ${colors.accentDark};
  --kr-text: ${colors.text};
  --kr-text-muted: ${colors.textMuted};
  --kr-border: ${colors.border};

  --kr-font-heading: ${typography.heading};
  --kr-font-body: ${typography.body};
}
`;

export default cssVariables;
