// Durations, in milliseconds.
//
// The loader is meant to register as a beat of brand, not a wait. Keep
// `minVisible` short — it exists so the screen never flashes in and out
// too fast to read, not to hold the visitor up.
const timing = {
  /** Floor on how long the overlay stays, even if the page is ready instantly. */
  minVisible: 900,
  /** Fade/slide-out duration once progress reaches 100%. */
  exit: 520,
  /** Progress creeps to this ceiling while waiting for the real load event. */
  creepCeiling: 0.9,
  /** How sharply the creep decelerates. Higher = slower approach to ceiling. */
  creepEasing: 1.7,
};

export default timing;
