// The site button system. Three variants, one base.
//
// Emitted globally by primitives/brand/brand-styles so any component can reach
// for `kr-btn kr-btn--gold` instead of restyling a button from scratch — the
// header CTA does exactly that.

import template1 from "./template-1";

export type ButtonsTemplate = {
  css: string;
  baseClass: string;
};

const { color, layout, spacing, typography } = template1;

const ease = "cubic-bezier(.4, 0, .2, 1)";

const css = `
.kr-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: ${spacing.iconGap}px;
  padding: ${spacing.paddingY}px ${spacing.paddingX}px;
  border: ${layout.borderWidth}px solid transparent;
  border-radius: ${layout.radius}px;
  font-family: ${typography.family};
  font-size: ${typography.size}px;
  font-weight: ${typography.weight};
  letter-spacing: ${typography.tracking};
  text-transform: ${typography.transform};
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color .26s ${ease},
    border-color .26s ${ease},
    color .26s ${ease},
    transform .16s ${ease};
}
.kr-btn:active { transform: translateY(${layout.activeShift}px); }
.kr-btn:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 3px;
}

/* ── primary dark ── */
.kr-btn--dark {
  background: ${color.darkBackground};
  border-color: ${color.darkBackground};
  color: ${color.darkText};
}
.kr-btn--dark:hover {
  background: ${color.darkHoverBackground};
  border-color: ${color.darkHoverBackground};
  color: ${color.darkHoverText};
}

/* ── gold CTA ── */
.kr-btn--gold {
  background: ${color.goldBackground};
  border-color: ${color.goldBackground};
  color: ${color.goldText};
}
.kr-btn--gold:hover {
  background: ${color.goldHoverBackground};
  border-color: ${color.goldHoverBackground};
  color: ${color.goldHoverText};
}

/* ── outline ── */
.kr-btn--outline {
  background: transparent;
  border-color: ${color.outlineBorder};
  color: ${color.outlineText};
}
.kr-btn--outline:hover {
  background: ${color.outlineHoverBackground};
  border-color: ${color.outlineHoverBackground};
  color: ${color.outlineHoverText};
}

/* ── sizes ── */
.kr-btn--sm {
  padding: ${spacing.paddingYSmall}px ${spacing.paddingXSmall}px;
  font-size: ${typography.sizeSmall}px;
}
.kr-btn--lg {
  padding: ${spacing.paddingYLarge}px ${spacing.paddingXLarge}px;
  font-size: ${typography.sizeLarge}px;
}

@media (prefers-reduced-motion: reduce) {
  .kr-btn { transition-duration: .01ms; }
}
`;

const template: ButtonsTemplate = {
  css,
  baseClass: "kr-btn",
};

export default template;
