import React from "react";

import type { LoadingLabels, LoadingTemplate } from "../../templates/loading/default-template";
import type { LoadingTiming } from "./types";
import useLoadingProgress from "./useLoadingProgress";

export type LoadingScreenProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: LoadingTemplate;
  /** Master switch. When false the overlay never paints. */
  enabled?: boolean;
  /** Show only on the first full page load of a browser session. */
  oncePerSession?: boolean;
  /** Copy overrides, merged over the template's labels. */
  labels?: Partial<LoadingLabels>;
  /** Timing overrides, merged over the template's timing. */
  timing?: Partial<LoadingTiming>;
};

/**
 * The loader mechanism: progress lifecycle and markup. Carries no colours,
 * sizes or copy of its own — those arrive via `template`, so restyling is a
 * template swap rather than a component edit.
 */
export default function LoadingScreen({
  template,
  enabled = true,
  oncePerSession = false,
  labels: labelOverrides,
  timing: timingOverrides,
}: LoadingScreenProps) {
  const labels = { ...template.labels, ...labelOverrides };
  const timing = { ...template.timing, ...timingOverrides };

  const { progress, phase } = useLoadingProgress({ enabled, oncePerSession, ...timing });

  if (phase === "done") return null;

  const percent = Math.round(progress * 100);
  const root = template.rootClass;

  return (
    <div
      className={`${root}${phase === "exiting" ? ` ${root}--exiting` : ""}`}
      role="status"
      aria-live="polite"
      aria-label={labels.srLabel}
    >
      <style>{template.css}</style>
      {/* Without JS the overlay would never be dismissed. */}
      <noscript>
        <style>{`.${root} { display: none; }`}</style>
      </noscript>

      <p className={`${root}__wordmark`}>
        {labels.wordmark}
        {labels.wordmarkAccent ? (
          <span className={`${root}__wordmark-accent`}>{labels.wordmarkAccent}</span>
        ) : null}
      </p>

      <div className={`${root}__center`}>
        <div className={`${root}__track`}>
          <div
            className={`${root}__fill`}
            style={{ transform: `scaleX(${progress})` }}
          />
        </div>
        {labels.counter ? (
          <span className={`${root}__counter`}>
            {labels.counter.replace("{n}", String(percent))}
          </span>
        ) : null}
      </div>
    </div>
  );
}
