// Structure and responsive sizing. No colour.
const layout = {
  /**
   * Ghost size drives everything else — the block's top padding is derived
   * from it below, so the overlap between ghost and heading stays constant at
   * every viewport instead of drifting as the clamp resolves differently.
   */
  ghostSize: "clamp(64px, 12.5vw, 220px)",
  /** A 1px rule disappears at 200px; 1.5 keeps the letterform legible. */
  ghostStrokeWidth: 1.5,
  ghostLeading: 0.8,
  /**
   * Approximate advance width of one uppercase glyph, in em, for the heading
   * face at weight 800. Used to shrink the ghost so a long word still fits its
   * container. Deliberately generous — spaces are far narrower than this, so
   * the estimate errs toward a slightly smaller word rather than a clipped one.
   */
  ghostGlyphWidth: 0.62,
  /**
   * Fraction of the ghost size used as top padding. The ghost starts at the
   * block's top edge, so this decides how much of it sits above the heading.
   */
  ghostOverlap: 0.42,
  /** Small optical pull so the ghost's side bearing lines up with the text. */
  ghostInset: "-0.045em",

  /** Short gold rule under the heading in the default variant. */
  ruleWidth: 56,
  ruleHeight: 2,

  /** Vertical divider between heading and description in the inline variant. */
  dividerWidth: 2,
  dividerHeight: 22,

  titleMaxWidth: "20ch",
  descriptionMaxWidth: "52ch",
  /** Inline variant gives the description more room since it sits alongside. */
  descriptionMaxWidthInline: "58ch",

  /** Below this the inline variant stacks. */
  stackInlineBelow: 860,
};

export default layout;
