import React from "react";

import buttons from "../../config/buttons--template";
import sectionTitle from "../../config/section-title--template";
import cssVariables from "../../templates/brand/cssVariables";

/**
 * Site-wide foundation: the brand tokens as CSS custom properties, the shared
 * button system, and the section-heading treatment.
 *
 * One style element rather than several, so cascade order is fixed and any
 * component can rely on `kr-btn` and `kr-sectitle` existing. The section
 * heading in particular renders on nearly every section of the site — emitting
 * its sheet per instance would duplicate it many times over.
 */
export default function BrandStyles() {
  return (
    <>
      <style>{cssVariables + buttons.css + sectionTitle.css}</style>
      {/* The heading reveal is driven by IntersectionObserver. Without
          JavaScript nothing would ever apply the revealed state, leaving every
          section title on the site invisible. */}
      <noscript>
        <style>{sectionTitle.noscriptCss}</style>
      </noscript>
    </>
  );
}
