// Kelley Road brand palette. Single source of truth for colour across the
// whole site — templates derive from this, components never hardcode a hex.
//
// Predominantly white. Charcoal carries contrast and weight; gold is an accent
// only — buttons, icons, hover states, small decorative rules. Never a surface.

const colors = {
  /** Main background. */
  background: "#FFFFFF",
  /** Light gray section background. */
  backgroundAlt: "#F1F2F4",

  /** Primary — charcoal. */
  primary: "#1F2328",
  /** Pressed/hover charcoal. Derived: same hue, a step deeper. */
  primaryDark: "#15181C",

  /** Accent — gold. Used sparingly. */
  accent: "#C89F5B",
  /** Hover state for gold surfaces. */
  accentDark: "#B08D4C",

  /** Main text. */
  text: "#33363A",
  /** Secondary text. */
  textMuted: "#777B80",

  /** Soft gray borders. */
  border: "#E6E7EA",

  /** On-dark counterparts, for surfaces sitting on `primary`. */
  onPrimary: "#FFFFFF",
  onPrimaryMuted: "rgba(255, 255, 255, 0.60)",
  onPrimaryFaint: "rgba(255, 255, 255, 0.16)",
};

export default colors;
