import brand from "../../brand";

// Colour only.
//
// The ghost word is the whole trick. The stroke alpha and the element opacity
// multiply: 0.20 at 0.75 lands around 15% effective, roughly double the first
// pass, which was sitting so close to the edge of perception that the effect
// barely registered. Still faint enough never to compete with the heading.
const color = {
  ghostStroke: "rgba(31, 35, 40, 0.20)",
  /** Multiplies with the stroke alpha above. */
  ghostOpacity: 0.75,

  title: brand.colors.primary,
  description: brand.colors.textMuted,

  /** The single decorative accent. Short gold rule, or vertical divider. */
  accent: brand.colors.accent,
};

export default color;
