// Structure and responsive sizing. No colour.
const layout = {
  /** Above every other fixed element on the site. */
  zIndex: 9999,

  /* Centred progress rule. Wider than it was when a counter sat beneath it:
     alone in the middle of the screen, a short stub reads like a stray mark,
     while a long thin line reads as deliberate. */
  trackWidth: 112,
  trackWidthWide: 156,
  trackHeight: 2,
  trackRadius: 0,

  /** Distance the overlay travels upward as it leaves. */
  exitTranslate: -12,

  /** Breakpoint below which the compact sizes apply. */
  compactBelow: 640,
};

export default layout;
