// Headings: Manrope — a clean modern sans with just enough character to carry
// a large heading, without the high-contrast serif curls of a display face.
// Body, navigation, buttons and forms: Inter.
//
// Both are sans, so headings earn their presence from weight and size rather
// than from a change of voice: `weight.heading` below is deliberately heavier
// than body copy, and `tracking.tight` is tighter than a serif would want,
// because large sans headings read loose at default spacing.
//
// To try a different heading face, change `sans`/`heading` here and the family
// in gatsby-ssr.tsx. Nothing else in the codebase names a typeface.

const heading = `"Manrope", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif`;
const sans = `"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif`;

const typography = {
  heading,
  body: sans,

  weight: {
    regular: 400,
    medium: 500,
    semibold: 600,
    bold: 700,
    /** Headings and display figures. */
    heading: 700,
  },

  tracking: {
    tight: "-0.03em",
    normal: "0",
    wide: "0.08em",
    wider: "0.16em",
  },
};

export default typography;
