import React from "react";
import type { GatsbyBrowser } from "gatsby";

import BrandStyles from "./src/ppm/primitives/brand/brand-styles";
import LoadingX from "./src/ppm/primitives/loading/loading-x";
import "./src/styles/global.css";

/**
 * wrapRootElement rather than wrapPageElement: the root persists across
 * in-site navigation, so the loader runs once per full page load instead of
 * re-mounting on every route change.
 */
export const wrapRootElement: GatsbyBrowser["wrapRootElement"] = ({ element }) => (
  <>
    <BrandStyles />
    <LoadingX />
    {element}
  </>
);
